// Deterministic availability check
const required = items[0].json.required_resources || items[0].json.resources_required || [];
const hospital = items[0].json;
const h = hospital.resources || hospital;
let missing = [];
for(const req of required){
  if(req.type==='bed'){
    const avail = (h.beds && (h.beds[req.subtype] && h.beds[req.subtype].available)) || (h.beds && h.beds[req.subtype.toLowerCase()] && h.beds[req.subtype.toLowerCase()].available) || 0;
    if(avail < req.count) missing.push({ item: `bed:${req.subtype}`, needed: req.count, available: avail });
  } else if(req.type==='blood_units'){
    const avail = (h.blood_units && (h.blood_units[req.subtype] || 0));
    if(avail < req.count) missing.push({ item: `blood:${req.subtype}`, needed: req.count, available: avail });
  } else if(req.type==='specialist'){
    const doctors = (h.doctors || []).filter(d => d.specialization && d.specialization.toLowerCase().includes(req.subtype.toLowerCase()));
    const oncall = doctors.filter(d => d.on_call).length;
    if(oncall < req.count) missing.push({ item: `specialist:${req.subtype}`, needed: req.count, available: oncall });
  } else if(req.type==='equipment'){
    const has = (h.equipment || []).includes(req.subtype);
    if(!has) missing.push({ item: `equipment:${req.subtype}`, needed: 1, available: 0 })
  }
}
const deterministic_ok = missing.length===0;
return [{ json: { hospital: hospital, deterministic_ok, missing_items: missing } }];
